#include <bits/stdc++.h>using namespace std; using int64 = long long; static inline int64 my_gcd(int64 a, int64 b) {    while (b) {        int64 t = a % b;        a = b;        b = t;    }    return a;} static inline int64 my_lcm(int64 a, int64 b) {    return a / my_gcd(a, b) * b;} bool can_change(const vector<int64>& a, int i) {    int n = (int)a.size() - 1;    int64 ai = a[i];     if (i == 1) {        int64 gR = my_gcd(ai, a[i + 1]);        if (gR != ai && my_gcd(gR, a[i + 1]) == gR) return true;        return false;    }     if (i == n) {        int64 gL = my_gcd(ai, a[i - 1]);        if (gL != ai && my_gcd(gL, a[i - 1]) == gL) return true;        return false;    }     int64 gL = my_gcd(ai, a[i - 1]);    int64 gR = my_gcd(ai, a[i + 1]);     int64 L = my_lcm(gL, gR);     if (L <= ai && L != ai) {        if (my_gcd(L, a[i - 1]) == gL && my_gcd(L, a[i + 1]) == gR) {            return true;        }    }     for (int64 k = 2; k * L <= ai && k <= 100; k++) {        int64 m = k * L;        if (m == ai) continue;        if (my_gcd(m, a[i - 1]) == gL && my_gcd(m, a[i + 1]) == gR) {            return true;        }    }     return false;} int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int T;    cin >> T;    while (T--) {        int n;        cin >> n;        vector<int64> a(n + 1), b(n + 1);        for (int i = 1; i <= n; i++) cin >> a[i];        for (int i = 1; i <= n; i++) cin >> b[i];         int ans = 0;        for (int i = 1; i <= n; i++) {            if (can_change(a, i)) ans++;        }        cout << ans << '\n';    }    return 0;}